-- Minimal reproduction of the deployed legacy schema, for exercising the real migration locally.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create schema storage;
grant usage on schema public,auth,storage to anon,authenticated,service_role;
create function auth.uid() returns uuid language sql stable as $$ select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
create function auth.role() returns text language sql stable as $$ select nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role' $$;
create table auth.users(id uuid primary key,email text unique,raw_user_meta_data jsonb,raw_app_meta_data jsonb,created_at timestamptz,updated_at timestamptz);
create table public.usuarios(id uuid primary key references auth.users(id),nome text not null,email text not null unique,barbearia_name text,role text default 'barbeiro' constraint usuarios_role_check check(role in ('admin','barbeiro')),created_at timestamptz default now(),hora_inicio text default '08:00',hora_fim text default '20:00',servicos_config jsonb,telefone text,modelo_atendimento text default 'agenda',status_fila text default 'disponivel',cpf_cnpj text,asaas_customer_id text,subscription_id text,status_assinatura text,plano text);
create table public.clientes(id uuid primary key default gen_random_uuid(),nome text not null,telefone text not null,intervalo_dias_retorno integer default 30,barber_id uuid not null references public.usuarios(id),created_at timestamptz default now());
create table public.atendimentos(id uuid primary key default gen_random_uuid(),cliente_id uuid not null references public.clientes(id),data timestamptz default now(),laterais text,topo text,barba text,produtos text,fotos text[]);
create table public.agendamentos(id uuid primary key default gen_random_uuid(),cliente_id uuid not null references public.clientes(id),data_hora timestamptz not null,servicos text,status text check(status in ('Pendente','Confirmado','Cancelado','Concluído')),barber_id uuid not null references public.usuarios(id),created_at timestamptz default now());
create table public.assinaturas_asaas(id text primary key,usuario_id uuid references public.usuarios(id),email_comprador text);
create table storage.buckets(id text primary key,public boolean);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text references storage.buckets(id),name text);
create function storage.foldername(name text) returns text[] language sql immutable as $$ select (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1] $$;
alter table storage.objects enable row level security;
insert into storage.buckets values('barbermemo-photos',true);
grant all on all tables in schema public to anon,authenticated,service_role;
grant all on all tables in schema storage to anon,authenticated,service_role;
create function public.handle_new_user() returns trigger language plpgsql security definer as $$ begin insert into public.usuarios(id,nome,email,role) values(new.id,'Legacy',new.email,coalesce(new.raw_user_meta_data->>'role','barbeiro'));return new;end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create function public.create_public_booking(uuid,text,text,timestamptz,text) returns jsonb language sql as $$ select '{}'::jsonb $$;
insert into auth.users(id,email,raw_user_meta_data) values('00000000-0000-4000-8000-000000000001','legacy-admin@example.invalid','{"role":"admin"}'),('00000000-0000-4000-8000-000000000002','legacy-barber@example.invalid','{}');
insert into public.clientes(nome,telefone,barber_id) values('Preservar cliente','11999990000','00000000-0000-4000-8000-000000000002');
alter table public.usuarios enable row level security;
create policy legacy_public on public.usuarios for select using(true);
create policy legacy_signup on public.usuarios for insert with check(true);
create policy legacy_billing on public.assinaturas_asaas for all using(true);
